from fractions import Fraction as F
import json

c = F(20, -24) - (2 + -3)
# f(x) = 1/16 x^4 + 1 + 1/8 x^2 + 0 x - c x^3  (ascending coefficients)
f = [F(1), F(0), F(1, 8), -c, F(1, 16)]
d = [i * f[i] for i in range(1, len(f))]  # derivative, ascending

def ev(p, x):
    return sum(co * x**i for i, co in enumerate(p))

def divide_root(p, r):
    # synthetic division of ascending poly p by (x - r)
    hi = p[::-1]
    out = [hi[0]]
    for co in hi[1:]:
        out.append(co + out[-1] * r)
    rem = out.pop()
    return out[::-1], rem

cands = sorted({F(p, q) for p in range(-12, 13) for q in range(1, 13)})
p = d[:]
roots = {}
for r in cands:
    while len(p) > 1 and ev(p, r) == 0:
        p, rem = divide_root(p, r)
        roots[r] = roots.get(r, 0) + 1

lc = p[0] if len(p) == 1 else None
complete = len(p) == 1

def fac(r, m):
    if r == 0:
        base = "x"
    elif r > 0:
        base = f"(x - {r})"
    else:
        base = f"(x + {-r})"
    if m > 1:
        base = base + f"**{m}" if r != 0 else base + f"**{m}"
    return base

if complete:
    parts = [fac(r, m) for r, m in sorted(roots.items())]
    # put x first
    parts.sort(key=lambda s: (s != "x" and not s.startswith("x**"), s))
    expr = "*".join(parts)
    if lc == 1:
        ans = expr
    elif lc.numerator == 1:
        ans = f"{expr}/{lc.denominator}"
    else:
        ans = f"{lc}*{expr}"
    print(json.dumps({"final_answer": ans,
                      "evidence": {"c": str(c), "k_coeffs_ascending": [str(x) for x in d],
                                   "roots": {str(r): m for r, m in roots.items()},
                                   "leading": str(lc)}}))
else:
    print("UNSUPPORTED")
